import inspect
from rich.repr import auto

class BadEq:
    def __eq__(self, other):
        return True

@auto
class Foo:
    def __init__(self, a=BadEq()):
        self.a = a

def test_custom_param():
    # If a is different from default, it should be shown.
    # But BadEq() == something is always True.
    f = Foo(a=1)
    # Expecting something like Foo(a=1)
    # If bug exists, it might be Foo() because default[0] == value is True
    repr_f = repr(f)
    print(f"repr(f): {repr_f}")
    assert "a=1" in repr_f

if __name__ == "__main__":
    test_custom_param()

